bash -c 'nvidia-smi; gcnt=$(nvidia-smi -L | wc -l); for ((g=0; g<gcnt; g++)); do mapfile -t plines < <(nvidia-smi -q -i "$g" | awk "/Process ID/ {p=\$4} /Used GPU Memory/ && p!=\"\" {print p, \$5\$6; p=\"\"}"); [ ${#plines[@]} -eq 0 ] && continue; echo "+-------gpu $g-----------------------------------------------------------------+"; s=0; for line in "${plines[@]}"; do pid=$(echo "$line" | awk "{print \$1}"); mem=$(echo "$line" | awk "{print \$2}"); num=$(echo "$mem" | sed "s/MiB//"); po="N/A"; if [ -f "/proc/$pid/cgroup" ]; then cid=$(awk -v FS="/" "{print \$NF}" "/proc/$pid/cgroup" | sed "s/\.scope$//" | sed "s/^docker-//" | cut -c 1-12 | head -n 1); [ -n "$cid" ] && name=$(docker inspect --format "{{.Name}}" "$cid" 2>/dev/null | sed "s/^\///") && [ -n "$name" ] && po="[docker]$name"; if [ "$po" = "N/A" ]; then svc=$(grep -o "[^/]*\.service" "/proc/$pid/cgroup" | head -n 1); [ -n "$svc" ] && po="[systemd]$svc"; fi; fi; printf "%-4s %-8s %-12s %s\n" "$g" "$pid" "$mem" "$po"; [ -n "$num" ] && s=$((s + num)); done; echo "Used GPU Memory Sum=${s} MiB"; done; echo "+-------all-------------------------------------------------------------------+"; nvidia-smi --query-gpu=timestamp,driver_version,name,index,memory.total,memory.used,memory.free,temperature.gpu,utilization.memory,pstate --format=csv; echo "+-----------------------------------------------------------------------------+"'
